-- D-07 / P-07 / PE-07 (supporting observation only; blocked composite facts)
WITH scope AS (SELECT unnest($2::text[]) AS record_id), activity AS (SELECT count(*)::bigint AS observed_sessions_capped_at_201, count(*) >= 201 AS sample_truncated FROM (SELECT 1 FROM pg_catalog.pg_stat_activity WHERE datname=current_database() AND pid<>pg_catalog.pg_backend_pid() LIMIT 201) bounded_activity) SELECT $1::text AS capture_id,$3::text AS chunk_id,scope.record_id,activity.observed_sessions_capped_at_201,activity.sample_truncated FROM scope CROSS JOIN activity LIMIT 1000;
-- D-08 / P-08 / PE-08
-- Runnable supporting observation only; does not satisfy the composite PE-08 requirement.
WITH scope AS (SELECT * FROM jsonb_to_recordset($5::jsonb) AS b(record_id text,schema_name text,object_name text,parent_name text)) SELECT $1::text AS capture_id,$4::text AS chunk_id,scope.record_id,(p.oid IS NOT NULL) AS object_found,n.nspname,p.proname,substring(pg_catalog.pg_get_function_identity_arguments(p.oid) FROM 1 FOR 256) AS argument_excerpt FROM scope LEFT JOIN pg_catalog.pg_namespace n ON n.nspname=scope.schema_name AND n.nspname=ANY($2::text[]) LEFT JOIN pg_catalog.pg_proc p ON p.pronamespace=n.oid AND p.proname=scope.object_name AND p.proname=ANY($3::text[]) LIMIT 500;
-- D-09 / P-09 / PE-09 (recovery metadata; restore proof blocked)
WITH scope AS (SELECT unnest($2::text[]) AS record_id) SELECT $1::text AS capture_id, $3::text AS chunk_id, scope.record_id, 'recovery_state' AS result_kind, pg_catalog.pg_is_in_recovery()::text AS result_value, true AS bounded, false AS truncation_applied FROM scope LIMIT 1000;
